def binary_search(arr, low, high, x):
    """
    This function performs binary search on a sorted array.

    Args:
        arr (list): A sorted list of integers.
        low (int): The starting index of the search range.
        high (int): The ending index of the search range.
        x (int): The target integer to find in the array.

    Returns:
        int: The index of the target integer if found, -1 otherwise.
    """

    if high >= low:
        mid = (high + low) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] > x:
            return binary_search(arr, low, mid - 1, x)
        else:
            return binary_search(arr, mid + 1, high, x)
    else:
        return -1
