            return Vector3D(self.x + other.x, self.y + other.y, self.z + other.z)
        elif isinstance(other, (int, float)):
            return Vector3D(self.x + other, self.y + other, self.z + other)
        else:
            raise TypeError("Unsupported operand type for +: {}".format(type(other)))

    def __sub__(self, other):
        """Subtracts this vector to another vector or a scalar value and returns the result.

        Args:
            other: A scalar value (float) or another Vector3D object.

        Returns:
            A new Vector3D object representing the result of the subtraction.

