            raise TypeError("Unsupported operand type for -: {}".format(type(other)))

    def __mul__(self, other):
        """Multiplies this vector by another vector or a scalar value and returns the result.

        Args:
            other: A scalar value (float) or another Vector3D object.

        Returns:
            A new Vector3D object representing the result of the multiplication.

        """
