import time
from functools import wraps

def class_method_timer(cls):
    """
    A class-level decorator to time the execution of a method.

    Applies to all methods of the class.
    """
    for name, method in cls.__dict__.items():
        if callable(method) and not name.startswith("__"):
            @wraps(method)
            def wrapper(*args, **kwargs):
                start_time = time.perf_counter()
                result = method(*args, **kwargs)
                end_time = time.perf_counter()
                elapsed_time = end_time - start_time
                print(f"{method.__name__} executed in {elapsed_time:.4f} seconds")
                return result
            setattr(cls, name, wrapper)
    return cls

@class_method_timer
class ExampleClass:
    def __init__(self):
        pass

    def method_to_time(self):
        time.sleep(1)  # Replace this with the actual method implementation

    def another_method(self):
        pass
```

