class MinHeap:
    def __init__(self, capacity):
        self.heap = [0] * capacity
        self.size = 0
        self.capacity = capacity

    def parent(self, i):
        return (i - 1) // 2

    def left_child(self, i):
        return 2 * i + 1

    def right_child(self, i):
        return 2 * i + 2

    def has_left_child(self, i):
        return self.left_child(i) < self.capacity

    def has_right_child(self, i):
        return self.right_child(i) < self.capacity

    def swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def min_heapify(self, i):
        smallest = i
        l = self.left_child(i)
        r = self.right_child(i)

        if l < self.capacity and self.heap[l] < self.heap[smallest]:
            smallest = l

        if r < self.capacity and self.heap[r] < self.heap[smallest]:
            smallest = r

        if smallest!= i:
            self.swap(i, smallest)
            self.min_heapify(smallest)

    def insert(self, key):
        if self.size == self.capacity:
            raise Exception('Heap is full')
        self.heap[self.size] = key
        self.size += 1
        self._bubble_up(self.size - 1)

    def _bubble_up(self, i):
        while i > 0 and self.heap[self.parent(i)] > self.heap[i]:
            self.swap(i, self.parent(i))
            i = self.parent(i)

    def extract_min(self):
        if self.size == 0:
            raise Exception('Heap is empty')
        if self.size == 1:
            self.size -= 1
            return self.heap[0]

        min_val = self.heap[0]
        self.heap[0] = self.heap[self.size - 1]
        self.size -= 1
        self.min_heapify(0)
        return min_val

    def build_heap(self, arr):
        self.size = len(arr)
        self.capacity = self.size
        self.heap = arr[:]
        for i in range(self.size // 2 - 1, -1, -1):
            self.min_heapify(i)
