import random

class MarkovModel:
    def __init__(self):
        self.model = {}

    def train(self, text):
        words = text.split()
        for i in range(1, len(words)):
            key = (words[i-1], words[i])
            value = words[i+1]
            if key in self.model:
                self.model[key].append(value)
            else:
                self.model[key] = [value]

    def generate(self, n=100):
        current_word, next_word = random.choice(list(self.model.keys()))
        output = [current_word, next_word]
        for _ in range(n-2):
            possible_words = self.model[(current_word, next_word)]
            next_word = random.choice(possible_words)
            output.append(next_word)
            current_word, next_word = next_word, next_word
        return''.join(output)

# Example usage
