    def __init__(self):
        """Initialize the linked list with a head node."""
        self.head = Node()

    def append(self, data):
        """Add a new node with the given data at the end of the list."""
        new_node = Node(data)

        if not self.head.next:
            self.head.next = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def prepend(self, data):
        """Add a new node with the given data at the beginning of the list."""
        new_node = Node(data)
        new_node.next = self.head.next
        self.head.next = new_node

    def delete(self, data):
        """Delete the first node with the given data."""
        if not self.head.next:
            return

        if self.head.next.data == data:
            self.head.next = self.head.next.next
            return

        current = self.head
        while current.next:
            if current.next.data == data:
                current.next = current.next.next
                return
            current = current.next

    def __str__(self):
        """Return a string representation of the linked list."""
        node_data = []
        current = self.head
        while current:
            node_data.append(str(current.next.data))
            current = current.next
        return'-> '.join(node_data)
